def quant_size(params_b, bits):
    if not isinstance(bits, int) or isinstance(bits, bool) or bits not in (8, 4):
        raise ValueError('unsupported bit width: ' + str(bits))
    return params_b * 1_000_000_000 * bits / 8 / 1_000_000_000

