def parse_bits(label):
    rest = label.split('Q', 1)[1]
    digits = ''
    for ch in rest:
        if ch.isdigit():
            digits += ch
        else:
            break
    return int(digits)


def pick_version(label, device_gb):
    bits = parse_bits(label)
    size = 7 * bits / 8
    if size + 2 <= device_gb:
        return label
    return 'none'


